export function bncSvg(lang,kind,mobile=false){
 if(typeof lang!=='string'||!['fr','en'].includes(lang)||typeof kind!=='string'||!BNC_KINDS.includes(kind)||typeof mobile!=='boolean')throw new TypeError('Invalid Bnc figure variant');
 return FIGURES[`${kind}-${lang}-${mobile?'mobile':'desktop'}`];
}
